// usage: node q.mjs build.nbt at x,y,z [x,y,z ...]  |  node q.mjs build.nbt slice y x0 x1 z0 z1
import { load } from "/Volumes/ext1/swe/repos/minecraft-design/tools/src/structure.mjs";
const [file, cmd, ...rest] = process.argv.slice(2);
const g = load(file);
const ab = (b) => b.replace("minecraft:", "");
if (cmd === "at") {
  for (const p of rest) { const [x, y, z] = p.split(",").map(Number); const c = g.get(x, y, z); console.log(`${x},${y},${z}: ${ab(g.blockAt(x, y, z))} ${c?.state ? JSON.stringify(c.state) : ""}`); }
} else if (cmd === "slice") {
  const [y, x0, x1, z0, z1] = rest.map(Number);
  const ch = (b) => { if (b === "minecraft:air") return "."; const n = ab(b); return n.slice(0, 2).toUpperCase(); };
  console.log(`y=${y}  x ${x0}..${x1} (cols), z ${z0}..${z1} (rows)`);
  let hdr = "     " + Array.from({ length: x1 - x0 + 1 }, (_, i) => String((x0 + i) % 100).padStart(3)).join("");
  console.log(hdr);
  for (let z = z0; z <= z1; z++) console.log(String(z).padStart(3) + "  " + Array.from({ length: x1 - x0 + 1 }, (_, i) => ch(g.blockAt(x0 + i, y, z)).padStart(3)).join(""));
} else if (cmd === "column") {
  const [x, z, y0, y1] = rest.map(Number);
  for (let y = y0; y <= y1; y++) { const c = g.get(x, y, z); console.log(`${x},${y},${z}: ${ab(g.blockAt(x, y, z))} ${c?.state ? JSON.stringify(c.state) : ""}`); }
}
