cat > /tmp/mcdq/intr.mjs <<'EOF'
import { load } from "/Volumes/ext1/swe/repos/minecraft-design/tools/src/structure.mjs";
import { ROOMS, OPENINGS } from "/Volumes/ext1/swe/repos/mc-design-eval/benchmarks/plugin-baseline/runs/build-1/mcmansion-sonnet-medium/vocab.mjs";
const g = load(process.argv[2]);
const inRoom = (x, y, z) => ROOMS.some(({ box: [x0, y0, z0, x1, y1, z1] }) => x >= x0 && x <= x1 && y >= y0 && y <= y1 && z >= z0 && z <= z1);
const inOpen = (x, y, z) => OPENINGS.some((o) => x >= o.x[0] && x <= o.x[1] && y >= o.y[0] && y <= o.y[1] && z >= o.z[0] && z <= o.z[1]);
const tally = {};
const cells = [];
for (const c of g.cells.values()) {
  const [x, y, z] = c.pos;
  if (y < 1 || y > 8) continue;
  if (!(inRoom(x, y, z) || inOpen(x, y, z))) continue;
  if (c.block === "minecraft:air") continue;
  const n = c.block.replace("minecraft:", "");
  tally[n] = (tally[n] || 0) + 1;
  if (/deepslate|blackstone|cobbled/.test(n)) cells.push(`${x},${y},${z} ${n}`);
}
console.log(JSON.stringify(tally));
console.log(cells.length, cells.join("  |  "));
EOF
node /tmp/mcdq/intr.mjs build.nbt 2>&1 | head -30

